import json
import pandas as pd
from acquire import ROOT
from settings import CONFIG
WEIGHTS=CONFIG['evidence_weights']
def score(components):
    if len(components)!=6 or any(not 0<=v<=5 for v in components): raise ValueError('Six components, 0..5 required')
    return sum(w*v for w,v in zip(WEIGHTS,components))
def main():
    inv={x['Mã nguồn']:x for x in json.loads((ROOT/'registry/inventory.json').read_text(encoding='utf-8'))}
    base={'affected_population':'người tham gia giao thông trong phạm vi nguồn; chưa xác nhận mẫu dự thi','ethics_privacy':'chỉ công bố số tổng hợp; xin phép địa bàn; không phát tán mặt/biển số/trẻ em','novelty_status':'NOT ESTABLISHED','baseline':'cần đo tại địa điểm thử nghiệm; số nguồn lịch sử không thay baseline hiện tại','evidence_status':'MEASURED DESCRIPTIVE; intervention remains HYPOTHESIS','data_gaps':'thiếu outcome tai nạn và mẫu số lưu lượng tại địa điểm can thiệp','next_test':'xác minh hiện trường trước chọn giải pháp','fatal_blocker':'permission_not_yet_obtained_for_field_intervention','confidence':'thấp về hiệu quả can thiệp; không phải xác suất','score_uncertainty':'thử từng thành phần ±1, chặn trong [0,5]; đánh giá chủ quan'}
    definitions=[
        ('P01','Danh mục Sơn La ghi nhận nhiều đoạn cong có mô tả tầm nhìn; cần kiểm chứng hiện trạng và ưu tiên xử lý đúng điểm.','1 (điểm nguy cơ; cần xác nhận phù hợp nút/điểm nóng)', 'Sơn La; 107 đoạn/vị trí được cơ quan chọn','snapshot 02/12/2025','GT-10;GT-11','record_mentions_visibility',48,'bản ghi',107,'data/processed/GT-10_coding.csv','E2','Cơ quan ưu tiên kiểm kê đường cong; mô tả lặp; biển/gương có thể đã có; chưa chứng minh thiếu hạ tầng.','Kiểm tra tầm nhìn và biển hiện hữu, bổ sung cảnh báo theo kỹ thuật được phê duyệt.','tỷ lệ xe tiếp cận vượt ngưỡng tốc độ được kỹ sư xác định','đo trước–sau có đoạn đối chứng tương đồng; không thử nghiệm gây nguy hiểm',[2,4,3,2,1,3]),
        ('P02','Cần kiểm chứng khả năng duy trì hành vi an toàn của học sinh sau giáo dục; bằng chứng lịch sử cho thấy hiệu quả đội mũ thay đổi theo thời điểm.','3 (cần xác nhận riêng học sinh tự lái xe điện)', '100 trường tại ba đô thị trong nghiên cứu lịch sử','03/2014–05/2016','GT-20;LIT-HELMET','reported_helmet_prevalence_followup',56.9,'phần trăm','84.218 lượt học sinh qua bốn đợt; n từng đợt chưa trích','reports/06_prior_art_vi.md','E1','Giáo dục, cưỡng chế và phụ huynh cùng thay đổi; nhóm hành khách khác học sinh tự lái xe điện; không chứng minh kỹ năng hiện tại thấp.','Bài tập tình huống tương tác và nhắc lại theo tuần; tham chiếu chương trình đã có.','tỷ lệ lựa chọn an toàn trong tình huống tương đương sau 1–2 tuần','ngẫu nhiên theo lớp nếu được phép; baseline và delayed control; phân tích theo cụm',[1,4,4,3,1,4]),
        ('P03','Hai đô thị có mức ùn tắc tổng hợp đáng chú ý; cần định vị nút và giờ cụ thể trước hỗ trợ điều tiết.','1','Hà Nội và TP.HCM theo vùng TomTom','2025 (TomTom); 2020–2021 (GT-07 riêng)','GT-06;GT-07;GT-16','published_congestion_HaNoi',49.2,'phần trăm','chỉ số nhà cung cấp; số chuyến probe không công khai','data/processed/GT-06_published_city_summary.csv','E1','Phủ probe, định nghĩa vùng, công trình và nhu cầu; tốc độ thấp không đồng nghĩa tai nạn; khác thời kỳ không xác nhận cùng nút.','Đo hàng chờ và luồng rẽ, quy trình hỗ trợ điều tiết có người phê duyệt; so với quy tắc cố định.','trễ mỗi xe và hàng chờ P95; xung đột là outcome phụ chỉ khi hiệu chỉnh hợp lệ','quan sát các ngày tương đồng trước–sau và nút đối chứng; không điều khiển đèn công cộng trái phép',[1,4,3,3,1,5]),
        ('P04','Danh mục Sơn La có các vị trí được ghi nguy cơ sạt lở; cần bổ sung nhật ký sự kiện để kiểm tra cơ chế mưa–gián đoạn giao thông.','1 (phù hợp cuộc thi còn hạn chế)','Sơn La; 58 vị trí do cơ quan chọn','snapshot 02/12/2025','GT-11;GT-18','listed_landslide_hazards',58,'vị trí',58,'data/processed/GT-11_hazards.csv','E2','Danh mục không phải sự kiện; địa chất, thi công và thoát nước có thể chi phối; thiếu mưa và ngày sự kiện.','Quy trình kiểm tra sau mưa và báo cáo đóng/mở đường do cơ quan vận hành.','thời gian từ phát hiện tới xác nhận/đặt cảnh báo; không dùng AUC nếu thiếu sự kiện','retrospective validation với nhật ký thật; sau đó pilot quy trình có giám sát',[2,4,2,1,1,2]),
        ('H01','[HYPOTHESIS] Hàng cồng kềnh có thể gây xung đột tại các vòng xuyến; chưa có số đếm hành vi riêng hoặc mức tác hại trong lần chạy.','2','chưa chọn địa điểm','chưa đo baseline','GT-08;GT-09','cargo_specific_observations',None,'NOT_MEASURED','NOT_AVAILABLE','data/processed/GT-08_binary_masks_summary.csv','E0','Nhãn abnormal không chỉ loại hàng; kích thước hộp ảnh không xác định kích thước hàng thật.','Thử quy trình lựa chọn phương tiện giao hàng phù hợp sau khảo sát người vận chuyển.','tỷ lệ chuyến vận chuyển được chuyên gia chấm không an toàn / tổng chuyến','đếm độc lập có định nghĩa hàng và đối chứng; không suy tỷ lệ từ benchmark',[0,4,2,2,1,5])]
    rows=[]
    for pid,statement,theme,geo,period,sids,metric,value,unit,denom,file,grade,alternatives,intervention,outcome,design,components in definitions:
        r={**base,'problem_id':pid,'problem_statement_vi':statement,'competition_theme':theme,'geographic_scope':geo,'temporal_scope':period,'source_ids':sids,'observed_metric':metric,'metric_value':value,'metric_unit':unit,'denominator':denom,'analysis_file':file,'evidence_strength':grade,'alternative_explanations':alternatives,'feasible_intervention':intervention,'primary_outcome':outcome,'evaluation_design':design,'source_citations':'; '.join(inv[s]['Link nguồn gốc'] for s in sids.split(';') if s in inv)}
        if pid=='P02': r['source_citations']+='; https://doi.org/10.1136/injuryprev-2017-042517'
        if grade=='E0': r['evidence_status']='HYPOTHESIS; NO EVIDENCE for cargo-specific harmful outcome'; r['fatal_blocker']='no_valid_cargo_outcome_or_baseline'
        for k,v in zip(['score_evidence','score_significance','score_actionability','score_feasibility','score_novelty','score_alignment'],components): r[k]=v
        r['weighted_score']=score(components); r['score_low']=score([max(0,v-1) for v in components]); r['score_high']=score([min(5,v+1) for v in components]); r['eligible_for_empirical_deployment']='NO; gates unresolved'; rows.append(r)
    df=pd.DataFrame(rows).sort_values('weighted_score',ascending=False); df.to_csv(ROOT/'reports/03_problem_evidence_matrix.csv',index=False,encoding='utf-8-sig')
    (ROOT/'reports/evidence_matrix.json').write_text(df.to_json(orient='records',force_ascii=False,indent=2),encoding='utf-8')
    print(df[['problem_id','evidence_strength','weighted_score']].to_string(index=False))
if __name__=='__main__': main()
